-- =====================================================================
--  Seed: every Indian state and UT with its districts, Nepal (7 provinces,
--  77 districts) and "NRI / Abroad" with the countries of the world.
--  Generated by tools/regions.py. Run after schema.sql. Safe to run twice.
--  Below the district (or country) members type their own block, panchayat
--  and village (Nepal: municipality, ward, village; abroad: state, city).
-- =====================================================================

on conflict do nothing;

update public.locations set region = v.r, name_hi = coalesce(public.locations.name_hi, v.h)
from (values
  ('Andhra Pradesh', 'आंध्र प्रदेश', 'india'),
  ('Arunachal Pradesh', 'अरुणाचल प्रदेश', 'india'),
  ('Assam', 'असम', 'india'),
  ('Chhattisgarh', 'छत्तीसगढ़', 'india'),
  ('Goa', 'गोवा', 'india'),
  ('Haryana', 'हरियाणा', 'india'),
  ('Himachal Pradesh', 'हिमाचल प्रदेश', 'india'),
  ('Kerala', 'केरल', 'india'),
  ('Maharashtra', 'महाराष्ट्र', 'india'),
  ('Manipur', 'मणिपुर', 'india'),
  ('Meghalaya', 'मेघालय', 'india'),
  ('Mizoram', 'मिज़ोरम', 'india'),
  ('Nagaland', 'नागालैंड', 'india'),
  ('Odisha', 'ओडिशा', 'india'),
  ('Punjab', 'पंजाब', 'india'),
  ('Sikkim', 'सिक्किम', 'india'),
  ('Tamil Nadu', 'तमिलनाडु', 'india'),
  ('Telangana', 'तेलंगाना', 'india'),
  ('Tripura', 'त्रिपुरा', 'india'),
  ('Uttarakhand', 'उत्तराखंड', 'india'),
  ('Andaman and Nicobar Islands', 'अंडमान और निकोबार द्वीप समूह', 'india'),
  ('Chandigarh', 'चंडीगढ़', 'india'),
  ('Dadra and Nagar Haveli and Daman and Diu', 'दादरा और नगर हवेली और दमन और दीव', 'india'),
  ('Delhi', 'दिल्ली', 'india'),
  ('Jammu and Kashmir', 'जम्मू और कश्मीर', 'india'),
  ('Ladakh', 'लद्दाख', 'india'),
  ('Lakshadweep', 'लक्षद्वीप', 'india'),
  ('Puducherry', 'पुडुचेरी', 'india'),
  ('Koshi', 'कोशी प्रदेश', 'nepal'),
  ('Madhesh', 'मधेश प्रदेश', 'nepal'),
  ('Bagmati', 'बागमती प्रदेश', 'nepal'),
  ('Gandaki', 'गण्डकी प्रदेश', 'nepal'),
  ('Lumbini', 'लुम्बिनी प्रदेश', 'nepal'),
  ('Karnali', 'कर्णाली प्रदेश', 'nepal'),
  ('Sudurpashchim', 'सुदूरपश्चिम प्रदेश', 'nepal'),
  ('NRI / Abroad', 'विदेश (NRI)', 'abroad')
) as v(n, h, r)
where level = 'state' and parent_id is null and name = v.n;

create temp table sd(state text, name text, name_hi text);

select 'district', sd.name, sd.name_hi, s.id
from sd join public.locations s on s.level = 'state' and s.parent_id is null and s.name = sd.state
on conflict do nothing;

drop table sd;

-- every place carries the region of its state (india / nepal / abroad)
update public.locations l set region = s.region from public.locations s
where s.id = l.path[1] and l.level <> 'state' and l.region is distinct from s.region;
